postData.text:
{"query":"query($windPowerTypes: [EntsoePowerTypeEnum!]){
  areas:entsoeAreas { name ...areaData }
}

fragment areaData on AreaData {
  ...powerTypeSpecificData
  loadYesterday
  powerTypes(name: $windPowerTypes) { name ...powerTypeSpecificData }
}

fragment powerTypeSpecificData on EntsoePowerTypeSpecificData {
  generation(powerTypes: { name: $windPowerTypes })
  generationHoursReported(powerTypes: { name: $windPowerTypes })
}","variables":{"windPowerTypes":["WIND_OFFSHORE","WIND_ONSHORE"]}}
